cd /home/john/mynotes/deterministic_equidistribution_theory/c_suite/out_kappa
echo "=== E killed-height, FULL group: kappa_Q and the argmin character ==="
echo "(phi/2 chars: Q=9->3, Q=27->9, Q=81->27) ; compare to char-cap-4 kappa: 0.093, 0.190, 0.306"
grep -v '^#' spectral_gaps.csv | grep -v '^Q,L' | awk -F, '
  $6!="trivial" && $5=="0.0000" {
    Q=$1; k=$7; gr=$17;   # gap_ratio_units
    if(!(Q in best)||gr>best[Q]){best[Q]=gr; bk[Q]=k}
    if(!(Q in worst)||gr<worst[Q]){worst[Q]=gr; wk[Q]=k}
    cnt[Q]++
  }
  END{ for(Q in best) printf "Q=%-4s nchars=%-3d  MAX gap_ratio=%.4f at k=%-3s (kappa_Q=%.4f)  | min ratio=%.4f at k=%s\n",
       Q,cnt[Q],best[Q],bk[Q],1-best[Q],worst[Q],wk[Q] }' | sort -t= -k2 -n
